import React, { useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { UserRound } from "lucide-react";
import { NavCover, useScreenTop } from "../components/ScreenTop";
import { HrNav } from "./hr";
import { YAI_DEPARTMENTS } from "./yaiStructure";

export const QMS_SECTION_ROWS = [
 {id:"sample", area:"0",leader:"Sample Room Quality Leader",teams:[{label:"Sample Room",unknown:true}]},
 {id:"fabric",area:"1",leader:"Warehouse · Fabric Quality Leader",teams:[{label:"Fabric Warehouse",unknown:true}]},
 {id:"accessory",area:"2",leader:"Warehouse · Accessory Quality Leader",teams:[{label:"Accessory Warehouse",unknown:true}]},
 {id:"cutting",area:"3",leader:"Fabric Inspection & Cutting Quality Leader",teams:[{label:"Cutting checkers",min:5,max:10},{label:"Fabric inspection",unknown:true}]},
 {id:"print",area:"4",leader:"Printing & Embroidery Quality Leader",teams:[{label:"Printing / Embroidery",unknown:true}]},
 ...Array.from({length:6},(_,g)=>({id:"sewing-"+g,area:"5",leader:`Sewing Quality Leader · L${String(g*5+1).padStart(2,"0")}–L${String(g*5+5).padStart(2,"0")}`,supervisor:"Senior Quality Supervisor · Internal",note:"Target 15–20 checkers per leader. Five lines at 2–3 gives 10–15; extra coverage to reconcile.",teams:Array.from({length:5},(_,l)=>({label:"Line "+String(g*5+l+1).padStart(2,"0"),min:2,max:3}))})),
 ...Array.from({length:4},(_,g)=>({id:"finishing-"+g,area:"6",leader:`Finishing Quality Leader · ${g+1}`,note:"One leader per three finishing lines; last group covers line 10.",teams:[{label:`Finishing lines ${g*3+1}–${Math.min(10,g*3+3)}`,min:15,max:20}]})),
 {id:"packing",area:"7",leader:"Packaging Quality Leaders · 2",teams:[{label:"Packing checkers · shared team",min:5,max:10}],note:"Split of checkers between the two leaders to confirm."},
 {id:"loading",area:"8",leader:"Loading Quality Leader",teams:[{label:"Loading",unknown:true}]},
 {id:"qa",leader:"QA auditors · department pool",teams:[{label:"QA · about 10 total",min:10,max:10}],note:"Allocate under area leaders; do not count ten again in every section."},
 ...Array.from({length:5},(_,i)=>({id:"qo-"+i,leader:`Brand QO · ${i+1}`,note:"Brand representative · warehouse / packaging / final quality. Brand name and reporting assignment to confirm.",teams:[{label:"QO support workers",min:1,max:2}]}))
];
function Slots({team}) {return <div className={`mb-3 ${team.max > 5 ? "xl:col-span-3" : ""}`}><h3 className="mb-2 text-xs font-bold text-slate-300">{team.label}{team.min ? ` · ${team.min}${team.max!==team.min?"–"+team.max:""} planned`:""}</h3>{team.unknown?<p className="text-xs text-slate-500">Staff allocation not specified yet.</p>:<div className="flex flex-wrap gap-2">{Array.from({length:team.max},(_,i)=><div key={i} className={`w-20 rounded-lg p-1 text-center ${i>=team.min?"border border-dashed border-slate-600 opacity-60":""}`}><div className="mx-auto flex h-10 w-10 items-center justify-center rounded-full border-2 border-slate-500 text-slate-500"><UserRound size={20}/></div><div className="mt-1 text-[10px] text-slate-400">ID unassigned</div><div className="text-[9px] text-slate-500">{i>=team.min?"Optional ":"Slot "}{i+1}</div></div>)}</div>}</div>;}
export default function YaiSectionList(){const [params]=useSearchParams();const [topRef,topPad]=useScreenTop();const [dept,setDept]=useState(params.get("department")||"all");const [area,setArea]=useState(params.get("area"));const departments=YAI_DEPARTMENTS.filter(d=>dept==="all"||d.id===dept);return <div ref={topRef} style={{paddingTop:topPad}} className="yai-pa-aware min-h-screen bg-slate-900 px-4 pb-8 text-slate-200"><NavCover/><div className="mb-3 flex flex-wrap items-center gap-3"><h1 className="text-lg font-black text-white">Section list</h1><HrNav current="sections"/></div><p className="mb-3 text-xs text-slate-400">Supervisor / leader on the left; workers on the right, grouped by line. Planned slots have no assigned employee ID. These are not employee records and are excluded from actual headcount.</p><div className="mb-4 flex flex-wrap gap-2">{[{id:"all",title:"All departments"},...YAI_DEPARTMENTS].map(d=><button key={d.id} onClick={()=>{setDept(d.id);setArea(null);}} aria-pressed={dept===d.id} className={`rounded-full border px-3 py-1 text-xs ${dept===d.id?"bg-white text-slate-900":"border-slate-600"}`}>{d.title}</button>)}<Link to="/dashboard/org-chart-master" className="ml-auto text-sm text-sky-300 underline">Master chart</Link></div>{departments.map(d=><section key={d.id} className="mb-5"><h2 className="mb-2 font-bold text-white">{d.title}</h2>{d.id==="qms"?QMS_SECTION_ROWS.filter(r=>!area||dept!=="qms"||r.area===area).map(r=><article key={r.id} className="mb-2 grid gap-4 rounded-xl border border-slate-700 bg-slate-800/40 p-3 md:grid-cols-[250px_minmax(0,1fr)]"><div className="md:border-r md:border-slate-700 md:pr-3"><div className="mb-2 text-xs text-slate-400">{r.supervisor||"Quality supervision / area allocation"}</div><div className="mx-auto mb-2 flex h-12 w-12 items-center justify-center rounded-full border-2 border-sky-500 text-sky-300 md:mx-0"><UserRound size={24}/></div><h3 className="font-bold text-white">{r.leader}</h3><p className="text-xs text-slate-400">Leader ID unassigned</p>{r.note&&<p className="mt-2 text-xs text-slate-400">{r.note}</p>}</div><div className="grid gap-3 xl:grid-cols-3">{r.teams.map(t=><Slots team={t} key={t.label}/>)}</div></article>):d.staff.map((s,i)=><article key={s.title} className="mb-2 grid gap-4 rounded-xl border border-slate-700 p-3 md:grid-cols-[250px_minmax(0,1fr)]"><div><h3 className="font-bold">{s.title}</h3><p className="text-xs text-slate-400">Leader / officer ID unassigned</p></div><div>{(s.children||[]).map(c=><div key={c.title} className="mb-2"><strong className="text-sm">{c.title}</strong><p className="text-xs text-slate-400">{c.detail||"Staff allocation to confirm"}</p></div>)}{!s.children&&<p className="text-xs text-slate-400">Staff allocation to confirm.</p>}</div></article>)}</section>)}</div>;}
